import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_30_safe_rl_overview.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_30_cmdp.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_30_lagrangian_cpo.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_30_shield.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_30_driving_safety_boundary.png",q=JSON.parse('{"title":"安全不只是扣分：Safe Reinforcement Learning（安全强化学习）如何把奖励、约束与安全屏障接起来","description":"强化学习如果只最大化回报，可能学会一条“得分很高但会撞车”的策略。Safe Reinforcement Learning（安全强化学习）要解决的不是把碰撞惩罚写得更大，而是把任务价值、风险预算、动作修正和运行时兜底放进同一条可验证链路。本篇从 reward（奖励）与 constraint（约束）的区","frontmatter":{"title":"安全不只是扣分：Safe Reinforcement Learning（安全强化学习）如何把奖励、约束与安全屏障接起来","description":"强化学习如果只最大化回报，可能学会一条“得分很高但会撞车”的策略。Safe Reinforcement Learning（安全强化学习）要解决的不是把碰撞惩罚写得更大，而是把任务价值、风险预算、动作修正和运行时兜底放进同一条可验证链路。本篇从 reward（奖励）与 constraint（约束）的区","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":17,"source":"2026-08-13/rl_series_30_safe_rl_constraints.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_30_safe_rl_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-30-safe-rl-constraints"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"安全不只是扣分：Safe Reinforcement Learning（安全强化学习）如何把奖励、约束与安全屏障接起来"}],["meta",{"property":"og:description","content":"强化学习如果只最大化回报，可能学会一条“得分很高但会撞车”的策略。Safe Reinforcement Learning（安全强化学习）要解决的不是把碰撞惩罚写得更大，而是把任务价值、风险预算、动作修正和运行时兜底放进同一条可验证链路。本篇从 reward（奖励）与 constraint（约束）的区"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-30-safe-rl-constraints"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_30_safe_rl_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"安全不只是扣分：Safe Reinforcement Learning（安全强化学习）如何把奖励、约束与安全屏障接起来"}],["meta",{"name":"twitter:description","content":"强化学习如果只最大化回报，可能学会一条“得分很高但会撞车”的策略。Safe Reinforcement Learning（安全强化学习）要解决的不是把碰撞惩罚写得更大，而是把任务价值、风险预算、动作修正和运行时兜底放进同一条可验证链路。本篇从 reward（奖励）与 constraint（约束）的区"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_30_safe_rl_overview.png"}]],"prev":{"text":"AlphaStar 拆解篇二：监督预训练、自博弈与联盟训练如何合成","link":"/rl/rl-series-29-alphastar-training-league"},"next":{"text":"强化学习学完之后怎么做研究？从算法选择到可信评价","link":"/rl/rl-series-31-research-evaluation"}},"headers":[],"relativePath":"rl/rl-series-30-safe-rl-constraints.md","filePath":"rl/rl-series-30-safe-rl-constraints.md","lastUpdated":null}'),d={name:"rl/rl-series-30-safe-rl-constraints.md"};function c(p,a,_,m,u,b){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="安全不只是扣分-safe-reinforcement-learning-安全强化学习-如何把奖励、约束与安全屏障接起来" tabindex="-1">安全不只是扣分：Safe Reinforcement Learning（安全强化学习）如何把奖励、约束与安全屏障接起来 <a class="header-anchor" href="#安全不只是扣分-safe-reinforcement-learning-安全强化学习-如何把奖励、约束与安全屏障接起来" aria-label="Permalink to &quot;安全不只是扣分：Safe Reinforcement Learning（安全强化学习）如何把奖励、约束与安全屏障接起来&quot;">​</a></h1><p>强化学习如果只最大化回报，可能学会一条“得分很高但会撞车”的策略。Safe Reinforcement Learning（安全强化学习）要解决的不是把碰撞惩罚写得更大，而是把任务价值、风险预算、动作修正和运行时兜底放进同一条可验证链路。本篇从 reward（奖励）与 constraint（约束）的区别出发，串起 CMDP（约束马尔可夫决策过程）、Lagrangian（拉格朗日）、CPO（约束策略优化）、shielding（安全屏蔽）和 Control Barrier Function（控制屏障函数），再落到自动驾驶实验设计。</p><p>本文的核心判断是：惩罚项只能表达偏好，约束算法只能在给定假设下管理风险，安全屏蔽与控制屏障函数才能在动作出口提供更接近硬边界的保护，但任何一层都不能替代传感器、动力学、延迟和回退控制器的验证。</p><h2 id="一、安全强化学习到底要保证什么" tabindex="-1">一、安全强化学习到底要保证什么 <a class="header-anchor" href="#一、安全强化学习到底要保证什么" aria-label="Permalink to &quot;一、安全强化学习到底要保证什么&quot;">​</a></h2><h3 id="_1-1-安全目标与任务目标必须分开" tabindex="-1">1.1 安全目标与任务目标必须分开 <a class="header-anchor" href="#_1-1-安全目标与任务目标必须分开" aria-label="Permalink to &quot;1.1 安全目标与任务目标必须分开&quot;">​</a></h3><p>普通强化学习把“走得快、到得远、得分高”统一写进一个回报函数；安全强化学习还要回答“哪些行为无论多高回报都不能接受”。车道偏离、碰撞、超出制动能力和违反执行器限制，不应只依赖一个可调的负奖励来表达。</p><h3 id="_1-2-软偏好不等于硬边界" tabindex="-1">1.2 软偏好不等于硬边界 <a class="header-anchor" href="#_1-2-软偏好不等于硬边界" aria-label="Permalink to &quot;1.2 软偏好不等于硬边界&quot;">​</a></h3><p>将奖励改成 (r_t-\\beta c_t) 可以让策略倾向于少犯危险，但有限的 (\\beta) 仍然允许策略用一次严重违规换取很多小收益，过大的 (\\beta) 又可能让策略停止探索或退化成过度保守。真正的约束需要明确预算、违反判定和不可接受的边界。</p><h3 id="_1-3-安全承诺必须带着适用条件" tabindex="-1">1.3 安全承诺必须带着适用条件 <a class="header-anchor" href="#_1-3-安全承诺必须带着适用条件" aria-label="Permalink to &quot;1.3 安全承诺必须带着适用条件&quot;">​</a></h3><p>“训练期间不违规”“每个状态都不违规”“一整个回合的违规概率很低”和“在所有扰动下都不违规”是不同的命题。它们对应不同的约束语义、数据要求和证明条件，不能用一条平均回报曲线互相替代。</p><h3 id="_1-4-自动驾驶需要分层安全链" tabindex="-1">1.4 自动驾驶需要分层安全链 <a class="header-anchor" href="#_1-4-自动驾驶需要分层安全链" aria-label="Permalink to &quot;1.4 自动驾驶需要分层安全链&quot;">​</a></h3><p>策略网络负责在可行空间里追求进度与舒适性，安全约束负责限制风险，动作屏蔽或投影负责拦截即时危险，底层执行器限制和回退控制器负责处理模型失配。把所有职责交给策略网络，既难训练，也难审计。</p><p><img src="'+n+'" alt="安全强化学习从奖励建模到动作出口的分层链路"></p><h2 id="二、奖励与约束为什么不能混成一个分数" tabindex="-1">二、奖励与约束为什么不能混成一个分数 <a class="header-anchor" href="#二、奖励与约束为什么不能混成一个分数" aria-label="Permalink to &quot;二、奖励与约束为什么不能混成一个分数&quot;">​</a></h2><h3 id="_2-1-reward-奖励-回答-行为有多有价值" tabindex="-1">2.1 reward（奖励）回答“行为有多有价值” <a class="header-anchor" href="#_2-1-reward-奖励-回答-行为有多有价值" aria-label="Permalink to &quot;2.1 reward（奖励）回答“行为有多有价值”&quot;">​</a></h3><p>奖励通常用于表达进度、到达目标、跟踪误差、乘坐舒适性和能耗等任务价值。它允许不同目标之间做权衡，因此适合驱动策略在安全可行区域内寻找更好的行为。</p><h3 id="_2-2-cost-代价-回答-风险消耗了多少预算" tabindex="-1">2.2 cost（代价）回答“风险消耗了多少预算” <a class="header-anchor" href="#_2-2-cost-代价-回答-风险消耗了多少预算" aria-label="Permalink to &quot;2.2 cost（代价）回答“风险消耗了多少预算”&quot;">​</a></h3><p>代价可以记录碰撞、车道边界穿越、最小车头时距不足、制动能力超限和动作修正等事件。不同代价的严重程度和单位可能不同，因此要与预算 (d_i) 比较，例如要求期望累计碰撞代价不超过给定阈值。</p><h3 id="_2-3-惩罚权重会掩盖量纲与时间尺度" tabindex="-1">2.3 惩罚权重会掩盖量纲与时间尺度 <a class="header-anchor" href="#_2-3-惩罚权重会掩盖量纲与时间尺度" aria-label="Permalink to &quot;2.3 惩罚权重会掩盖量纲与时间尺度&quot;">​</a></h3><p>奖励的单位可能是前进距离，代价的单位可能是事件次数，二者经过折扣后还会受时间尺度影响。若只调一个惩罚权重，实验结果可能只是权重选择的结果；必须同时报告原始奖励、各类代价、预算、折扣因子和违规判定窗口。</p><h3 id="_2-4-约束语义决定安全结论" tabindex="-1">2.4 约束语义决定安全结论 <a class="header-anchor" href="#_2-4-约束语义决定安全结论" aria-label="Permalink to &quot;2.4 约束语义决定安全结论&quot;">​</a></h3><p>期望累计约束要求 (\\mathbb E[\\sum_t\\gamma^t c_t]\\le d)，它允许少量轨迹出现严重事故，只要平均值没有超预算。状态级约束要求每个可达状态都满足局部条件，机会约束限制违规概率，几乎必然约束则要求在环境随机性下以概率为一成立。自动驾驶论文如果只写“安全”，却不写是哪一种语义，结论就不完整。</p><h2 id="三、cmdp-约束马尔可夫决策过程-怎样把安全正式写进强化学习" tabindex="-1">三、CMDP（约束马尔可夫决策过程）怎样把安全正式写进强化学习 <a class="header-anchor" href="#三、cmdp-约束马尔可夫决策过程-怎样把安全正式写进强化学习" aria-label="Permalink to &quot;三、CMDP（约束马尔可夫决策过程）怎样把安全正式写进强化学习&quot;">​</a></h2><h3 id="_3-1-从-mdp-马尔可夫决策过程-扩展到-cmdp-约束马尔可夫决策过程" tabindex="-1">3.1 从 MDP（马尔可夫决策过程）扩展到 CMDP（约束马尔可夫决策过程） <a class="header-anchor" href="#_3-1-从-mdp-马尔可夫决策过程-扩展到-cmdp-约束马尔可夫决策过程" aria-label="Permalink to &quot;3.1 从 MDP（马尔可夫决策过程）扩展到 CMDP（约束马尔可夫决策过程）&quot;">​</a></h3><p>Markov Decision Process（马尔可夫决策过程，MDP）通常用 ((\\mathcal S,\\mathcal A,P,r,\\gamma)) 表示状态、动作、转移、奖励和折扣因子。Constrained Markov Decision Process（约束马尔可夫决策过程，CMDP）再加入代价函数 (c_i(s,a)) 与预算 (d_i)，让策略同时承担任务目标和风险限制。</p><h3 id="_3-2-目标函数与约束函数各自有名字" tabindex="-1">3.2 目标函数与约束函数各自有名字 <a class="header-anchor" href="#_3-2-目标函数与约束函数各自有名字" aria-label="Permalink to &quot;3.2 目标函数与约束函数各自有名字&quot;">​</a></h3><p>对策略 (\\pi)，可以写成</p><p>$$ J_R(\\pi)=\\mathbb E_\\pi\\left[\\sum_{t=0}^{T-1}\\gamma^t r_t\\right] $$</p><p>并要求</p><p>$$ J_{C_i}(\\pi)=\\mathbb E_\\pi\\left[\\sum_{t=0}^{T-1}\\gamma^t c_{i,t}\\right]\\le d_i，\\qquad i=1,\\ldots,m。 $$</p><p>这样，“更快到达”由 (J_R) 体现，“碰撞风险不超过预算”由 (J_{C_i}\\le d_i) 体现，调参时可以知道是哪一层出了问题。</p><h3 id="_3-3-多个风险通道需要分别记录" tabindex="-1">3.3 多个风险通道需要分别记录 <a class="header-anchor" href="#_3-3-多个风险通道需要分别记录" aria-label="Permalink to &quot;3.3 多个风险通道需要分别记录&quot;">​</a></h3><p>把碰撞、车道越界、舒适性和执行器饱和全部压成一个代价，会丢失风险来源。更可审计的做法是保留多个 (c_i)，分别设置预算，并在报告中展示每个通道的均值、尾部值、最大值和触发时刻。</p><h3 id="_3-4-不可行问题没有算法捷径" tabindex="-1">3.4 不可行问题没有算法捷径 <a class="header-anchor" href="#_3-4-不可行问题没有算法捷径" aria-label="Permalink to &quot;3.4 不可行问题没有算法捷径&quot;">​</a></h3><p>如果车辆动力学、道路宽度、观测延迟和给定预算互相矛盾，可能不存在满足全部约束的策略。此时应重新检查约束定义、预算和动作能力，或者显式引入松弛变量并报告松弛量；继续调学习率不会把不可行问题变成可行问题。</p><p><img src="'+l+'" alt="CMDP 中奖励目标、风险代价与预算约束的关系"></p><h2 id="四、lagrangian-拉格朗日-怎样让策略在风险预算上学习" tabindex="-1">四、Lagrangian（拉格朗日）怎样让策略在风险预算上学习 <a class="header-anchor" href="#四、lagrangian-拉格朗日-怎样让策略在风险预算上学习" aria-label="Permalink to &quot;四、Lagrangian（拉格朗日）怎样让策略在风险预算上学习&quot;">​</a></h2><h3 id="_4-1-拉格朗日函数把约束残差变成自适应价格" tabindex="-1">4.1 拉格朗日函数把约束残差变成自适应价格 <a class="header-anchor" href="#_4-1-拉格朗日函数把约束残差变成自适应价格" aria-label="Permalink to &quot;4.1 拉格朗日函数把约束残差变成自适应价格&quot;">​</a></h3><p>Lagrangian（拉格朗日）方法对每个约束引入非负乘子 (\\lambda_i)，构造</p><p>$$ \\mathcal L(\\pi,\\lambda)=J_R(\\pi)-\\sum_{i=1}^{m}\\lambda_i\\left(J_{C_i}(\\pi)-d_i\\right)，\\qquad \\lambda_i\\ge0。 $$</p><p>当代价低于预算时，约束残差为负，乘子不会继续放大惩罚；当代价超过预算时，乘子上升，策略更新会更加关注风险。</p><h3 id="_4-2-原问题和对偶问题要交替更新" tabindex="-1">4.2 原问题和对偶问题要交替更新 <a class="header-anchor" href="#_4-2-原问题和对偶问题要交替更新" aria-label="Permalink to &quot;4.2 原问题和对偶问题要交替更新&quot;">​</a></h3><p>实践中可以用奖励评论家和代价评论家估计优势，再用</p><p>$$ \\hat A_t=\\hat A_t^R-\\sum_i\\lambda_i\\hat A_{i,t}^C $$</p><p>更新策略，同时用</p><p>$$ \\lambda_i\\leftarrow\\left[\\lambda_i+\\eta_\\lambda\\left(\\hat J_{C_i}-d_i\\right)\\right]_+ $$</p><p>更新乘子。方括号表示投影到非负区域，(\\eta_\\lambda) 是对偶步长。</p><h3 id="_4-3-乘子不是安全证明" tabindex="-1">4.3 乘子不是安全证明 <a class="header-anchor" href="#_4-3-乘子不是安全证明" aria-label="Permalink to &quot;4.3 乘子不是安全证明&quot;">​</a></h3><p>拉格朗日方法把预算违反转换成更新信号，仍会受到有限样本、代价估计偏差、策略分布漂移和双时间尺度选择影响。即使训练曲线暂时低于预算，也不能直接推断每个状态或每条轨迹都安全。</p><h3 id="_4-4-诊断要围绕预算而不是只看回报" tabindex="-1">4.4 诊断要围绕预算而不是只看回报 <a class="header-anchor" href="#_4-4-诊断要围绕预算而不是只看回报" aria-label="Permalink to &quot;4.4 诊断要围绕预算而不是只看回报&quot;">​</a></h3><p>需要同时观察每个乘子、代价估计、预算残差、策略熵、动作修正和回合终止原因。乘子持续增大说明约束可能不可行或代价估计失真，乘子大幅振荡说明批次噪声、步长或奖励代价尺度需要重新检查。</p><p><img src="'+o+'" alt="拉格朗日乘子与 CPO（约束策略优化）策略更新的风险预算视角"></p><h2 id="五、cpo-约束策略优化-怎样把策略更新限制在局部可行域" tabindex="-1">五、CPO（约束策略优化）怎样把策略更新限制在局部可行域 <a class="header-anchor" href="#五、cpo-约束策略优化-怎样把策略更新限制在局部可行域" aria-label="Permalink to &quot;五、CPO（约束策略优化）怎样把策略更新限制在局部可行域&quot;">​</a></h2><h3 id="_5-1-cpo-约束策略优化-不只是在奖励上加一个惩罚" tabindex="-1">5.1 CPO（约束策略优化）不只是在奖励上加一个惩罚 <a class="header-anchor" href="#_5-1-cpo-约束策略优化-不只是在奖励上加一个惩罚" aria-label="Permalink to &quot;5.1 CPO（约束策略优化）不只是在奖励上加一个惩罚&quot;">​</a></h3><p>Constrained Policy Optimization（约束策略优化，CPO）把策略更新写成带信赖域和代价约束的局部优化问题。它在每轮更新中同时考虑回报提升、代价变化和新旧策略之间的距离，而不是只依赖一个固定惩罚系数。</p><h3 id="_5-2-信赖域控制策略分布跳变" tabindex="-1">5.2 信赖域控制策略分布跳变 <a class="header-anchor" href="#_5-2-信赖域控制策略分布跳变" aria-label="Permalink to &quot;5.2 信赖域控制策略分布跳变&quot;">​</a></h3><p>令 (x) 表示策略参数更新方向，(g) 表示回报梯度，(b) 表示代价梯度，(H) 表示局部曲率近似，可以得到类似的局部问题</p><p>$$ \\max_x\\quad g^\\mathsf T x $$</p><p>满足</p><p>$$ b^\\mathsf T x+J_C(\\pi_{\\mathrm{old}})-d\\le0，\\qquad \\frac12x^\\mathsf T Hx\\le\\delta。 $$</p><p>其中第二个条件对应新旧策略的平均 KL 散度（Kullback–Leibler divergence，库尔贝克—莱布勒散度）信赖域。它的意义是限制局部近似失效的幅度。</p><h3 id="_5-3-近似满足约束依赖估计与模型假设" tabindex="-1">5.3 近似满足约束依赖估计与模型假设 <a class="header-anchor" href="#_5-3-近似满足约束依赖估计与模型假设" aria-label="Permalink to &quot;5.3 近似满足约束依赖估计与模型假设&quot;">​</a></h3><p>CPO 论文给出逐次更新的近约束满足分析，并在模拟机器人任务上验证策略搜索能力。这个结论依赖采样估计、策略距离界、代价函数和环境假设；它不是对任意真实道路、感知错误和执行延迟的绝对安全保证。</p><h3 id="_5-4-lagrangian-拉格朗日-与-cpo-约束策略优化-的选择取决于代价结构" tabindex="-1">5.4 Lagrangian（拉格朗日）与 CPO（约束策略优化）的选择取决于代价结构 <a class="header-anchor" href="#_5-4-lagrangian-拉格朗日-与-cpo-约束策略优化-的选择取决于代价结构" aria-label="Permalink to &quot;5.4 Lagrangian（拉格朗日）与 CPO（约束策略优化）的选择取决于代价结构&quot;">​</a></h3><p>拉格朗日方法实现较直接，适合快速探索多个约束和大规模策略更新，但预算附近可能振荡。CPO 更直接地处理局部可行更新，却需要代价梯度、曲率近似、线搜索和较高计算开销。实验应在相同采样预算下比较，而不是只比较某一次的最高回报。</p><h2 id="六、shielding-安全屏蔽-怎样在动作出口拦截危险行为" tabindex="-1">六、Shielding（安全屏蔽）怎样在动作出口拦截危险行为 <a class="header-anchor" href="#六、shielding-安全屏蔽-怎样在动作出口拦截危险行为" aria-label="Permalink to &quot;六、Shielding（安全屏蔽）怎样在动作出口拦截危险行为&quot;">​</a></h2><h3 id="_6-1-动作屏蔽先缩小可选集合" tabindex="-1">6.1 动作屏蔽先缩小可选集合 <a class="header-anchor" href="#_6-1-动作屏蔽先缩小可选集合" aria-label="Permalink to &quot;6.1 动作屏蔽先缩小可选集合&quot;">​</a></h3><p>安全屏蔽器可以根据当前状态和安全规范生成 (A_{\\mathrm{safe}}(s))，让策略只在安全动作集合中采样。这种动作掩码适合离散动作或能可靠枚举可行动作的场景，但连续控制通常需要可行性判定或投影器。</p><h3 id="_6-2-动作监控器可以替换危险动作" tabindex="-1">6.2 动作监控器可以替换危险动作 <a class="header-anchor" href="#_6-2-动作监控器可以替换危险动作" aria-label="Permalink to &quot;6.2 动作监控器可以替换危险动作&quot;">​</a></h3><p>另一种结构让策略先提出 (a_{\\mathrm{rl}})，屏蔽器检查它是否会违反规范；若会违反，就输出备份动作 (a_{\\mathrm{backup}})。这样可以保留策略的表达能力，又在动作出口提供保护，但必须记录提出动作、执行动作和替换原因。</p><h3 id="_6-3-安全规范与模型决定屏蔽器能看见什么" tabindex="-1">6.3 安全规范与模型决定屏蔽器能看见什么 <a class="header-anchor" href="#_6-3-安全规范与模型决定屏蔽器能看见什么" aria-label="Permalink to &quot;6.3 安全规范与模型决定屏蔽器能看见什么&quot;">​</a></h3><p>Safe Reinforcement Learning via Shielding（通过安全屏蔽实现安全强化学习）讨论了决策前提供安全动作集合，以及决策后监控并修正动作两类方式。屏蔽器可以基于时序逻辑、有限状态机、可达性模型或验证器，但规范遗漏、模型不准和未知状态都会削弱结论。</p><h3 id="_6-4-干预会改变策略学习的数据分布" tabindex="-1">6.4 干预会改变策略学习的数据分布 <a class="header-anchor" href="#_6-4-干预会改变策略学习的数据分布" aria-label="Permalink to &quot;6.4 干预会改变策略学习的数据分布&quot;">​</a></h3><p>如果训练时只把原始动作送进损失，却把修正后的动作送进环境，策略看到的行为分布与执行分布会不一致。可以记录干预率并把风险修正纳入训练信号，也可以让策略学习安全动作集合；具体做法要与同策略或异策略更新假设保持一致。</p><p><img src="'+h+'" alt="屏蔽器对策略动作进行检查、替换与回退的闭环"></p><h2 id="七、cbf-控制屏障函数-如何把连续控制写成安全边界" tabindex="-1">七、CBF（控制屏障函数）如何把连续控制写成安全边界 <a class="header-anchor" href="#七、cbf-控制屏障函数-如何把连续控制写成安全边界" aria-label="Permalink to &quot;七、CBF（控制屏障函数）如何把连续控制写成安全边界&quot;">​</a></h2><h3 id="_7-1-安全集先定义状态空间里的允许区域" tabindex="-1">7.1 安全集先定义状态空间里的允许区域 <a class="header-anchor" href="#_7-1-安全集先定义状态空间里的允许区域" aria-label="Permalink to &quot;7.1 安全集先定义状态空间里的允许区域&quot;">​</a></h3><p>对连续系统</p><p>$$ \\dot x=f(x)+g(x)u， $$</p><p>可以用函数 (h(x)) 定义安全集</p><p>$$ \\mathcal C={x\\mid h(x)\\ge0}。 $$</p><p>例如 (h(x)) 可以表示车辆到车道边界的剩余距离、与前车的安全距离或可用制动裕度。边界 (h(x)=0) 不是抽象分数，而是必须结合车辆几何、延迟和预测误差解释的物理条件。</p><h3 id="_7-2-屏障不等式约束状态离开安全集的趋势" tabindex="-1">7.2 屏障不等式约束状态离开安全集的趋势 <a class="header-anchor" href="#_7-2-屏障不等式约束状态离开安全集的趋势" aria-label="Permalink to &quot;7.2 屏障不等式约束状态离开安全集的趋势&quot;">​</a></h3><p>Control Barrier Function（控制屏障函数，CBF）常用条件为</p><p>$$ \\dot h(x,u)+\\alpha(h(x))\\ge0， $$</p><p>其中 (\\alpha) 是满足适当性质的类函数。若系统模型、可观测状态和输入能力满足假设，持续满足该不等式可以推出安全集的前向不变性，也就是状态不会从安全集内直接越过边界。</p><h3 id="_7-3-二次规划把策略动作投影到可行集合" tabindex="-1">7.3 二次规划把策略动作投影到可行集合 <a class="header-anchor" href="#_7-3-二次规划把策略动作投影到可行集合" aria-label="Permalink to &quot;7.3 二次规划把策略动作投影到可行集合&quot;">​</a></h3><p>策略输出 (u_{\\mathrm{rl}}) 后，可以求解</p><p>$$ u^*=\\arg\\min_u\\frac12\\left|u-u_{\\mathrm{rl}}\\right|_R^2 $$</p><p>满足</p><p>$$ \\dot h(x,u)+\\alpha(h(x))\\ge0，\\qquad u_{\\min}\\le u\\le u_{\\max}。 $$</p><p>这类 Quadratic Program（二次规划，QP）在尽量保留策略意图的同时，满足局部安全不等式；多条边界可以形成多个约束，动作变化率也应作为执行器约束加入。</p><h3 id="_7-4-cbf-控制屏障函数-边界不是无条件的碰撞证明" tabindex="-1">7.4 CBF（控制屏障函数）边界不是无条件的碰撞证明 <a class="header-anchor" href="#_7-4-cbf-控制屏障函数-边界不是无条件的碰撞证明" aria-label="Permalink to &quot;7.4 CBF（控制屏障函数）边界不是无条件的碰撞证明&quot;">​</a></h3><p>若安全函数依赖有误差的感知，车辆存在输入延迟，系统具有更高相对阶，或二次规划没有可行解，单步 CBF 条件就可能不足。工程上需要考虑高阶屏障函数、离散时间多步预测、鲁棒裕度和不可行时的安全停车或备份控制器；使用松弛变量时必须把松弛量当作违规证据记录。</p><p><img src="'+s+'" alt="车道边界、碰撞距离与 CBF 可行控制区域"></p><h2 id="八、训练与部署怎样各自承担安全责任" tabindex="-1">八、训练与部署怎样各自承担安全责任 <a class="header-anchor" href="#八、训练与部署怎样各自承担安全责任" aria-label="Permalink to &quot;八、训练与部署怎样各自承担安全责任&quot;">​</a></h2><h3 id="_8-1-训练阶段要限制探索造成的伤害" tabindex="-1">8.1 训练阶段要限制探索造成的伤害 <a class="header-anchor" href="#_8-1-训练阶段要限制探索造成的伤害" aria-label="Permalink to &quot;8.1 训练阶段要限制探索造成的伤害&quot;">​</a></h3><p>训练环境应有动作幅值、加速度、转向速率和碰撞终止条件，并用屏蔽器、CBF（控制屏障函数）或可验证动力学模型限制明显危险动作。真实车辆不应承担未经验证的随机探索，复杂场景应在仿真、封闭场地或受控数据回放中逐步增加难度。</p><h3 id="_8-2-训练日志要区分提出动作与执行动作" tabindex="-1">8.2 训练日志要区分提出动作与执行动作 <a class="header-anchor" href="#_8-2-训练日志要区分提出动作与执行动作" aria-label="Permalink to &quot;8.2 训练日志要区分提出动作与执行动作&quot;">​</a></h3><p>每个时间步至少记录观测版本、策略提出动作、屏蔽或投影后的执行动作、触发的约束、回退原因、代价通道和终止类型。只记录执行动作会掩盖策略本身的风险，只记录提出动作又无法反映车辆真正执行的行为。</p><h3 id="_8-3-部署链路需要独立的运行时监控" tabindex="-1">8.3 部署链路需要独立的运行时监控 <a class="header-anchor" href="#_8-3-部署链路需要独立的运行时监控" aria-label="Permalink to &quot;8.3 部署链路需要独立的运行时监控&quot;">​</a></h3><p>部署时可以形成“观测质量检查—策略决策—安全屏蔽或 CBF（控制屏障函数）投影—执行器限制—回退控制器”的链路。运行时监控器应检查传感器超时、状态越界、预测不确定性、屏蔽器不可行和控制延迟；任何一个模块异常都应进入预先定义的低风险状态。</p><h3 id="_8-4-上线门槛要覆盖最坏情况与恢复能力" tabindex="-1">8.4 上线门槛要覆盖最坏情况与恢复能力 <a class="header-anchor" href="#_8-4-上线门槛要覆盖最坏情况与恢复能力" aria-label="Permalink to &quot;8.4 上线门槛要覆盖最坏情况与恢复能力&quot;">​</a></h3><p>接受测试不能只看平均回报，应在固定的压力场景和未见场景上检查碰撞、越界、最小安全裕度、回退触发、动作延迟和恢复时间。通过门槛应在实验前冻结，不能为了让结果通过而事后调整预算或删除失败回合。</p><h2 id="九、自动驾驶实验怎样证明方法确实更安全" tabindex="-1">九、自动驾驶实验怎样证明方法确实更安全 <a class="header-anchor" href="#九、自动驾驶实验怎样证明方法确实更安全" aria-label="Permalink to &quot;九、自动驾驶实验怎样证明方法确实更安全&quot;">​</a></h2><h3 id="_9-1-从小型车道保持任务定义清晰接口" tabindex="-1">9.1 从小型车道保持任务定义清晰接口 <a class="header-anchor" href="#_9-1-从小型车道保持任务定义清晰接口" aria-label="Permalink to &quot;9.1 从小型车道保持任务定义清晰接口&quot;">​</a></h3><p>可以用横向误差、航向误差、速度、道路曲率、前车相对距离和观测延迟构造低维状态，策略输出转向曲率或转角与加速度。动作边界、车辆轴距、采样周期、噪声和延迟都应写进环境定义，而不是藏在脚本默认值里。</p><h3 id="_9-2-奖励和代价要覆盖进度与风险来源" tabindex="-1">9.2 奖励和代价要覆盖进度与风险来源 <a class="header-anchor" href="#_9-2-奖励和代价要覆盖进度与风险来源" aria-label="Permalink to &quot;9.2 奖励和代价要覆盖进度与风险来源&quot;">​</a></h3><p>奖励可以表达前进、跟踪误差、平顺性和能耗，代价则分别记录车道越界、碰撞、车头时距不足、制动能力超限、转向速率超限和安全过滤干预。每个代价的触发条件、单位、折扣、预算和回合终止规则都要可复现。</p><h3 id="_9-3-基线与消融要形成可解释对照" tabindex="-1">9.3 基线与消融要形成可解释对照 <a class="header-anchor" href="#_9-3-基线与消融要形成可解释对照" aria-label="Permalink to &quot;9.3 基线与消融要形成可解释对照&quot;">​</a></h3><p>建议同时保留 PID（比例—积分—微分）或 Stanley（斯坦利横向控制器）基线、无约束 PPO（近端策略优化）或 SAC（软演员—评论家）、固定惩罚、拉格朗日更新、CPO（约束策略优化）、单独屏蔽器和 CBF（控制屏障函数）组合。消融时保持地图、策略网络、采样步数、随机种子和执行器限制一致，才能知道安全收益来自约束算法还是回退控制器。</p><h3 id="_9-4-场景划分要让分布外风险显形" tabindex="-1">9.4 场景划分要让分布外风险显形 <a class="header-anchor" href="#_9-4-场景划分要让分布外风险显形" aria-label="Permalink to &quot;9.4 场景划分要让分布外风险显形&quot;">​</a></h3><p>评估应包含正常曲率、急弯、窄车道、前车急减速、感知噪声、观测延迟、动作速率限制和未见组合场景。训练与测试不能共享会泄漏未来信息的轨迹，压力场景应固定版本、地图、动力学参数和随机种子。</p><h3 id="_9-5-指标必须同时呈现平均与尾部" tabindex="-1">9.5 指标必须同时呈现平均与尾部 <a class="header-anchor" href="#_9-5-指标必须同时呈现平均与尾部" aria-label="Permalink to &quot;9.5 指标必须同时呈现平均与尾部&quot;">​</a></h3><p>除回报和到达率外，还应报告碰撞率、越界率、每回合违规次数、最小屏障值、最小车头时距、代价预算违反率、屏蔽干预率、动作修正幅度、舒适性和控制计算延迟。对多随机种子给出均值、离散程度和最差结果，避免一次幸运运行决定结论。</p><h2 id="十、哪些结果不能被包装成安全进展" tabindex="-1">十、哪些结果不能被包装成安全进展 <a class="header-anchor" href="#十、哪些结果不能被包装成安全进展" aria-label="Permalink to &quot;十、哪些结果不能被包装成安全进展&quot;">​</a></h2><h3 id="_10-1-低平均代价不代表没有严重事故" tabindex="-1">10.1 低平均代价不代表没有严重事故 <a class="header-anchor" href="#_10-1-低平均代价不代表没有严重事故" aria-label="Permalink to &quot;10.1 低平均代价不代表没有严重事故&quot;">​</a></h3><p>期望累计代价可能把一次碰撞稀释在很多无事故轨迹中。必须把硬违规作为独立指标，并说明它是逐步约束、回合约束、概率约束还是平均预算约束。</p><h3 id="_10-2-屏蔽器介入后的安全不等于策略学会安全" tabindex="-1">10.2 屏蔽器介入后的安全不等于策略学会安全 <a class="header-anchor" href="#_10-2-屏蔽器介入后的安全不等于策略学会安全" aria-label="Permalink to &quot;10.2 屏蔽器介入后的安全不等于策略学会安全&quot;">​</a></h3><p>如果大多数危险动作都由 Stanley（斯坦利横向控制器）、MPC（模型预测控制）或安全投影器接管，安全结果主要来自这些组件。报告应区分策略原始行为、屏蔽器贡献、回退控制器贡献和最终执行结果，不能把最终零碰撞直接称为“策略独立学会安全”。</p><h3 id="_10-3-训练安全不等于部署安全" tabindex="-1">10.3 训练安全不等于部署安全 <a class="header-anchor" href="#_10-3-训练安全不等于部署安全" aria-label="Permalink to &quot;10.3 训练安全不等于部署安全&quot;">​</a></h3><p>训练环境里没有未建模障碍、传感器故障和执行器延迟，不代表道路系统也没有。部署前需要做模型参数扰动、传感器丢帧、时间同步、计算超时和执行器饱和测试，并验证回退路径本身不会制造新的危险。</p><h3 id="_10-4-从-toy-简化实验-结果到真实道路必须保持证据边界" tabindex="-1">10.4 从 toy（简化实验）结果到真实道路必须保持证据边界 <a class="header-anchor" href="#_10-4-从-toy-简化实验-结果到真实道路必须保持证据边界" aria-label="Permalink to &quot;10.4 从 toy（简化实验）结果到真实道路必须保持证据边界&quot;">​</a></h3><p>低维车道保持任务可以验证约束定义、代价记录、屏蔽逻辑和统计流程，但不能证明真实交通中的泛化能力。安全强化学习的下一步应是把小实验的指标和日志规范保留下来，再逐步加入动态障碍、部分可观测性和更真实的动力学，而不是直接放大网络规模。</p><h2 id="十一、把安全强化学习做成可复现实验" tabindex="-1">十一、把安全强化学习做成可复现实验 <a class="header-anchor" href="#十一、把安全强化学习做成可复现实验" aria-label="Permalink to &quot;十一、把安全强化学习做成可复现实验&quot;">​</a></h2><h3 id="_11-1-最小闭环应包含策略与安全出口" tabindex="-1">11.1 最小闭环应包含策略与安全出口 <a class="header-anchor" href="#_11-1-最小闭环应包含策略与安全出口" aria-label="Permalink to &quot;11.1 最小闭环应包含策略与安全出口&quot;">​</a></h3><p>一个可复现的最小闭环应同时运行策略、代价估计、约束更新、动作屏蔽或 CBF（控制屏障函数）投影、执行器限制和回退控制器。每次运行固定环境版本、配置、随机种子、策略版本和安全模块版本，并保留原始轨迹。</p><h3 id="_11-2-研究问题要对应可检验假设" tabindex="-1">11.2 研究问题要对应可检验假设 <a class="header-anchor" href="#_11-2-研究问题要对应可检验假设" aria-label="Permalink to &quot;11.2 研究问题要对应可检验假设&quot;">​</a></h3><p>不要只问“哪种算法回报更高”，可以改问“在相同采样预算下，CPO（约束策略优化）是否降低预算违反率”“屏蔽器干预率下降是否伴随策略原始动作更安全”“CBF（控制屏障函数）的鲁棒裕度是否能覆盖给定延迟”。每个问题都要预先写出对照、指标和停止条件。</p><h3 id="_11-3-结论应写清楚安全来自哪里" tabindex="-1">11.3 结论应写清楚安全来自哪里 <a class="header-anchor" href="#_11-3-结论应写清楚安全来自哪里" aria-label="Permalink to &quot;11.3 结论应写清楚安全来自哪里&quot;">​</a></h3><p>最终报告应分别说明奖励设计、CMDP（约束马尔可夫决策过程）约束、拉格朗日乘子、CPO（约束策略优化）更新、屏蔽器、CBF（控制屏障函数）、执行器限制和回退控制器的作用边界。只有这样，实验才从“跑出一条曲线”变成可以复查的安全证据。</p><h3 id="_11-4-下一篇实验评价要接住安全指标" tabindex="-1">11.4 下一篇实验评价要接住安全指标 <a class="header-anchor" href="#_11-4-下一篇实验评价要接住安全指标" aria-label="Permalink to &quot;11.4 下一篇实验评价要接住安全指标&quot;">​</a></h3><p>安全强化学习的核心不是给普通强化学习加一个更大的负数，而是把风险语义、约束预算、可行动作、运行时保护和实验评价连成闭环。后续实验应沿着低维基线、约束更新、安全屏蔽、连续边界和分布外评估逐步增加复杂度，同时保留失败记录与证据边界。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://arxiv.org/abs/1705.10528" target="_blank" rel="noreferrer">Achiam 等《Constrained Policy Optimization（约束策略优化）》</a></p><p><a href="https://arxiv.org/abs/1708.08611" target="_blank" rel="noreferrer">Alshiekh 等《Safe Reinforcement Learning via Shielding（通过安全屏蔽实现安全强化学习）》</a></p><p><a href="https://arxiv.org/abs/1609.06408" target="_blank" rel="noreferrer">Ames 等《Control Barrier Function Based Quadratic Programs for Safety Critical Systems（面向安全关键系统的基于控制屏障函数的二次规划）》</a></p><p><a href="https://arxiv.org/abs/2205.06750" target="_blank" rel="noreferrer">Krasowski 等《Provably Safe Reinforcement Learning: Conceptual Analysis, Survey, and Benchmarking（可证明安全强化学习：概念分析、综述与基准）》</a></p>',138)])])}const g=e(d,[["render",c]]);export{q as __pageData,g as default};
